style.css:
/* Cat Theme for Stylish */
body {
    background-color: #FBE3E8; /* Soft pink for a cozy feel */
    color: #333;
    font-family: 'Comic Sans MS', cursive, sans-serif; /* Playful font */
}

/* Cat paw prints */
body::after {
    content: "";
    background: url('https://www.transparenttextures.com/patterns/cats.png'); /* Cat paw texture */
    opacity: 0.3;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
}

/* Links with cat vibes */
a {
    color: #FF6F61;
    text-decoration: none;
}

a:hover {
    color: #D85A50;
    text-shadow: 0 0 5px #FFB6C1; /* Glowy effect */
}

/* Custom cursor */
body {
    cursor: url('https://www.example.com/cat-cursor.png'), auto;
}

/* Rounded buttons with a cat-ear shape */
button {
    background-color: #FFB6C1;
    border: none;
    padding: 10px 20px;
    border-radius: 20px;
    font-size: 16px;
    cursor: pointer;
    position: relative;
}

button::before,
button::after {
    content: "";
    position: absolute;
    width: 10px;
    height: 10px;
    background-color: #FFB6C1;
    border-radius: 50%;
    top: -5px;
}

button::before {
    left: 10px;
}

button::after {
    right: 10px;
}
